#include "easy/Easy.h"
using namespace acs::easy;
int main() {
    OpenWindow(1280, 720, "はじめてのゲーム");
    float x = 600;
    while (NextFrame()) {                 // 閉じると false
        if (IsKeyDown(EKey::Right)) x += 5;
        if (IsKeyDown(EKey::Left))  x -= 5;
        DrawRect(x, 320, 80, 80, FColor::Sky);
    }
}
